<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ReportController extends Controller {
 public function index(Request $r){$v=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from','format'=>'nullable|in:csv,xlsx']);$u=auth()->user();
  if($u->role==='seller')$q=DB::table('orders')->where('seller_id',$u->id)->select('id','status','merchandise_total','store_discount','commission','shipping_fee','total','created_at','completed_at');
  elseif($u->role==='admin')$q=DB::table('orders')->select('id','seller_id','status','merchandise_total','store_discount','commission','shipping_fee','total','created_at');
  elseif($u->role==='sorting_center'){$center=DB::table('sorting_centers')->where('user_id',$u->id)->value('id');$q=DB::table('parcels')->where('center_id',$center)->select('id','order_id','tracking_code','status','attempts','created_at');}
  else abort(403);
  if(!empty($v['from']))$q->whereDate('created_at','>=',$v['from']);if(!empty($v['to']))$q->whereDate('created_at','<=',$v['to']);$rows=$q->orderBy('id')->get();
  $headers=$u->role==='sorting_center'?['id','order_id','tracking_code','status','attempts','created_at']:($u->role==='seller'?['id','status','merchandise_total','store_discount','commission','shipping_fee','total','created_at','completed_at']:['id','seller_id','status','merchandise_total','store_discount','commission','shipping_fee','total','created_at']);
  if($r->format==='csv')return response()->streamDownload(function()use($rows,$headers){$f=fopen('php://output','w');fputcsv($f,$headers);foreach($rows as $row)fputcsv($f,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@-]/',$v)?"'".$v:$v,(array)$row));fclose($f);},'lokashop-report.csv',['Content-Type'=>'text/csv']);
  if($r->format==='xlsx')return $this->xlsx($headers,$rows);
  return view('tools',['title'=>'Filtered report','records'=>$rows,'forms'=>[],'links'=>app(CommonController::class)->links(),'report'=>true]);
 }
 private function xlsx(array $headers,$rows){$path=tempnam(sys_get_temp_dir(),'lokashop-');$zip=new \ZipArchive();$zip->open($path,\ZipArchive::OVERWRITE);$zip->addFromString('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Report" sheetId="1" r:id="rId1"/></sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');$xml='<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';$data=[$headers];foreach($rows as $row)$data[]=array_values((array)$row);foreach($data as $row){$xml.='<row>';foreach($row as $value){if(is_int($value)||is_float($value))$xml.='<c><v>'.$value.'</v></c>';else $xml.='<c t="inlineStr"><is><t xml:space="preserve">'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';}$xml.='</row>';}$zip->addFromString('xl/worksheets/sheet1.xml',$xml.'</sheetData></worksheet>');$zip->close();return response()->download($path,'lokashop-report.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])->deleteFileAfterSend(true);}
}
